import { Component, Element, h } from "@stencil/core";

/**
 * @since 1.1.20
 * @status dev
 *
 * @slot - The activity timeline default content for all panels.
 *
 */
@Component({
	tag: "hbr-timeline",
	styleUrl: "activity-timeline.scss",
	shadow: true,
})
export class Timeline {
	@Element() host: HTMLHbrTimelineElement;
	componentDidLoad() {
		const ulElements = this.host.shadowRoot
			? this.host.shadowRoot.querySelector("ul")
			: null;
		if (ulElements?.children) {
			// Use type assertion to treat the first child as HTMLSlotElement
			const firstChild = ulElements.children[0] as HTMLSlotElement;
			const assignedNodes = firstChild.assignedNodes();
			const arrayLength = assignedNodes.length;
			if (arrayLength > 0) {
				// Ensure the last node is treated as an HTMLElement to use setAttribute
				const lastNode = assignedNodes[arrayLength - 1] as HTMLElement;
				lastNode?.setAttribute?.("last", "true");
			}
		}
	}
	render() {
		return (
			<ul class="dnx-activity-timeline-accordion-list">
				<slot />
			</ul>
		);
	}
}
